// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public {
        c = new Roulette();
    }

    function testFuzz_property(uint256 block1Timestamp, uint256 block2Timestamp) public {
        vm.assume(block1Timestamp > 0);
        vm.assume(block2Timestamp >= block1Timestamp);
        vm.assume(block2Timestamp < type(uint256).max);

        vm.warp(block1Timestamp);

        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "First call failed");
        uint256 pastAfterFirst = c.pastBlockTime();

        vm.warp(block2Timestamp);

        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        if (ok2) {
            uint256 pastAfterSecond = c.pastBlockTime();
            assertTrue(pastAfterSecond > pastAfterFirst, "pastBlockTime must strictly increase on success");
        }
    }
}
